// The credits page (/credits/, Page.astro with generated: "dependencies") prints each package's author
// from its package.json, or else the copyright line of its licence file, as found. A licence file may
// be Markdown: svelte's LICENSE.md reads "Copyright (c) 2016-2025 [Svelte Contributors](https://github.com/
// sveltejs/svelte/graphs/contributors)", and the "Author and source" cell printed that raw Markdown
// (round 1 confirmer of the pages cluster). The table is generated by site/src/lib/pages/dependencies.ts.
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { dependencyRows, plainText } from '../../src/lib/pages/dependencies';

/** Markdown that must not reach a cell of the credits table. */
const RAW_MARKDOWN = /\[[^\]]*\]\([^)]*\)|<https?:\/\/|\*\*|\]\(/;

describe('credits page: every cell is plain text', () => {
  // regression: RT-FIX residual (round 1 confirmer of the pages cluster)
  it('no field of any row shows raw Markdown link syntax', () => {
    const rows = dependencyRows();
    expect(rows.length).toBeGreaterThan(5);
    const bad = rows.flatMap((r) =>
      Object.entries(r)
        .flatMap(([field, v]) => (Array.isArray(v) ? v.map((x) => [field, x] as const) : [[field, v] as const]))
        .filter(([, v]) => typeof v === 'string' && RAW_MARKDOWN.test(v))
        .map(([field, v]) => `${r.name}.${field}: ${v}`),
    );
    expect(bad).toEqual([]);
  });

  // regression: RT-FIX residual (round 1 confirmer of the pages cluster)
  it('svelte: the copyright line of its Markdown licence is printed as text', () => {
    const licence = readFileSync(fileURLToPath(new URL('../../../node_modules/svelte/LICENSE.md', import.meta.url)), 'utf8');
    // The input still is Markdown, so this test keeps guarding the conversion.
    expect(licence.split('\n')[0]).toMatch(/\[Svelte Contributors\]\(https:\/\/github\.com\/sveltejs\/svelte\/graphs\/contributors\)/);
    const svelte = dependencyRows().find((r) => r.name === 'svelte');
    expect(svelte?.author).toMatch(/^Copyright \(c\) \d{4}-\d{4} Svelte Contributors$/);
  });

  it('plainText reduces links, autolinks and emphasis to text', () => {
    expect(plainText('Copyright (c) 2016-2025 [Svelte Contributors](https://github.com/sveltejs/svelte/graphs/contributors)')).toBe('Copyright (c) 2016-2025 Svelte Contributors');
    expect(plainText('Copyright **Jane Doe** <https://example.org/x>')).toBe('Copyright Jane Doe https://example.org/x');
    expect(plainText('Copyright (c) _The Authors_.')).toBe('Copyright (c) The Authors.');
    // Plain lines pass unchanged, underscores inside a word included.
    expect(plainText('Copyright (c) 2013-present, Yuxi (Evan) You')).toBe('Copyright (c) 2013-present, Yuxi (Evan) You');
    expect(plainText('some_name_here')).toBe('some_name_here');
  });
});
